t:class.t:resource:
.gl-unit-log {
	position: absolute;
	max-width: 600px;
	top: 10px;
	right: 10px;
	padding: 5px;
	color: black;
	background-color: #ddf;
	font-family: Arial, sans-serif;
	font-size: smaller;
	opacity: 0.8;
	border-radius: 5px;
	-moz-border-radius: 5px;
	-webkit-border-radius: 5px;
}
.gl-unit-log h2 {
	margin: -5px -5px 5px -5px;
	padding: 5px;
	background-color: #ccf;
	border-radius: 5px 5px 0 0;
	border-top-left-radius: 5px;
	border-top-right-radius: 5px;
	-moz-border-radius-topleft: 5px;
	-moz-border-radius-topright: 5px;
	-webkit-border-top-left-radius: 5px;
	-webkit-border-top-right-radius: 5px;
}

t:class.t:method:
var oView = gl.core.Component.prototype.createView.call(this, oDocument);
var aTests = this.model._getTests();
for (var i = 0; i < aTests.length; i++) {
	oView.appendChild(new gl.unit.LogMessage(aTests[i]).getView(oDocument));
}
var oCompleted = oDocument.createElement('div');
var sCompleted = this.model.errors ? 'Unit tests completed with ' + this.model.errors + ' errors.' : 'Unit tests completed.';
oCompleted.appendChild(oDocument.createTextNode(sCompleted));
oView.appendChild(oCompleted);
var oTime = oDocument.createElement('div');
oTime.appendChild(oDocument.createTextNode('Time taken: ' + this.model.getTime() + 'ms'));
oView.appendChild(oTime);
return oView;

var oView = gl.core.Component.prototype.createView.call(this, oDocument);
oView.appendChild(oDocument.createTextNode(this.model.toString()));
if (!this.model.hasCompleted()) {
	oView.className += ' gl-notcompleted';
}
if (this.model.getError()) {
	oView.className += ' gl-error';
	oView.appendChild(oDocument.createTextNode(' — Error: ' + (this.model.getError().message || this.model.getError())));
}
if (this.model.hasCompleted() && this.model.getTime() > 8) {
	oView.appendChild(oDocument.createTextNode(' — time taken: ' + this.model.getTime() + 'ms'));
}
return oView;
